(82,'{"version":1,"target":"employee","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"f0_taetigkeit_zeitraum_und_anlass","label":"Tätigkeit, Zeitraum und Anlass","type":"multiline","required":true},{"key":"f1_qualifikation_aufgaben_und_zustaendigkeit","label":"Qualifikation, Aufgaben und Zuständigkeit","type":"multiline","required":false},{"key":"f2_vereinbarungen_und_festgestellter_bedarf","label":"Vereinbarungen und festgestellter Bedarf","type":"multiline","required":false},{"key":"f3_nachweise_freigabe_und_wiedervorlage","label":"Nachweise, Freigabe und Wiedervorlage","type":"multiline","required":false}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"confidentiality","heading":"1. Vertraulicher Umgang","text":"Personenbezogene Angaben, Gesundheitsdaten und interne Informationen dürfen nur für die übertragenen Aufgaben und im erforderlichen Umfang verarbeitet werden. Zugänge werden persönlich verwendet und nicht weitergegeben. Einsichtnahmen ohne dienstlichen Anlass sowie private Kopien sind unzulässig."},{"key":"security","heading":"2. Schutz und Vorfälle","text":"Unterlagen und Endgeräte werden vor unbefugtem Zugriff geschützt. Die benannten Sicherheits- und Meldewege gelten auch bei Verlust, Fehlversand oder vermuteter Offenlegung. Vorfälle werden unverzüglich an die zuständige Stelle gemeldet; eigenmächtige Löschung möglicher Nachweise unterbleibt."},{"key":"duration","heading":"3. Ende der Tätigkeit","text":"Die Verpflichtung zur Vertraulichkeit besteht nach Ende der Tätigkeit fort. Unterlagen, Schlüssel und Zugänge werden übergeben beziehungsweise entzogen. Gesetzliche Auskunftsrechte und zulässige Meldungen an zuständige Stellen bleiben gewahrt."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
