(85,'{"version":1,"target":"company","sourceMode":"create","layout":"table","orientation":"landscape","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"f0_geltungsbereich_und_ziel_des_verfahrens","label":"Geltungsbereich und Ziel des Verfahrens","type":"multiline","required":true},{"key":"f1_ablauf_und_verantwortlichkeiten","label":"Ablauf und Verantwortlichkeiten","type":"multiline","required":false},{"key":"f2_feststellungen_risiken_und_nachweise","label":"Feststellungen, Risiken und Nachweise","type":"multiline","required":false},{"key":"f3_verbesserungsmassnahme_termin_und_wirksamkeitskont","label":"Verbesserungsmaßnahme, Termin und Wirksamkeitskontrolle","type":"multiline","required":false}],"columns":["Datum / Zeitraum","Gegenstand / Maßnahme","Ergebnis / Menge","Abweichung / Hinweis","Zuständigkeit"],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(86,'{"version":1,"target":"company","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"f0_geltungsbereich_und_ziel_des_verfahrens","label":"Geltungsbereich und Ziel des Verfahrens","type":"multiline","required":true},{"key":"f1_ablauf_und_verantwortlichkeiten","label":"Ablauf und Verantwortlichkeiten","type":"multiline","required":false},{"key":"f2_feststellungen_risiken_und_nachweise","label":"Feststellungen, Risiken und Nachweise","type":"multiline","required":false},{"key":"f3_verbesserungsmassnahme_termin_und_wirksamkeitskont","label":"Verbesserungsmaßnahme, Termin und Wirksamkeitskontrolle","type":"multiline","required":false}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"parties","heading":"§ 1 Vertragsparteien und Gegenstand","text":"Die im Dokument eindeutig bezeichneten Parteien vereinbaren die dort beschriebenen Leistungen. Vertretung und Zeichnungsbefugnis werden vor Abschluss geprüft. Art, Umfang, Beginn und Ort ergeben sich aus den ausgefüllten Vereinbarungen und den ausdrücklich einbezogenen Anlagen. Nicht ausgefüllte Angaben müssen vor Abschluss ergänzt werden."},{"key":"services","heading":"§ 2 Vereinbarter Umfang und Durchführung","text":"Die Leistungserbringung richtet sich nach dem individuell vereinbarten Bedarf, den fachlichen Zuständigkeiten und den beigefügten Leistungsbeschreibungen. Änderungen werden besprochen, dokumentiert und mit einer nachvollziehbaren Kosteninformation versehen. Medizinische Leistungen erfordern die einschlägigen Voraussetzungen und eine gültige Anordnung, soweit vorgeschrieben. Eine Vereinbarung ersetzt keine ärztliche Entscheidung."},{"key":"costs","heading":"§ 3 Vergütung und Kosteninformation","text":"Vergütung, Leistungspositionen, Abrechnungseinheit, Fälligkeit und gegebenenfalls Eigenanteile werden vor Vertragsschluss transparent ausgewiesen. Leistungen zu Lasten eines Kostenträgers werden nur innerhalb der einschlägigen Voraussetzungen abgerechnet. Eine Kostenübernahme wird nicht allein durch den Vertrag zugesichert. Tatsächliche Leistungen werden nachgewiesen; Abweichungen und nicht gedeckte Kosten werden vor einer zusätzlichen Beauftragung erläutert."},{"key":"cooperation","heading":"§ 4 Mitwirkung, Selbstbestimmung und Sicherheit","text":"Die Beteiligten benennen erreichbare Kontaktstellen und teilen relevante Änderungen zeitnah mit. Wünsche, Einwilligungen und nachgewiesene Vertretungsbefugnisse werden berücksichtigt. Sicherheitsrelevante Abweichungen werden dokumentiert und an die zuständige Person weitergegeben. Freiheitsbeschränkende Maßnahmen sind durch diesen Vertrag nicht pauschal gestattet."},{"key":"data","heading":"§ 5 Dokumentation und Datenschutz","text":"Erforderliche Daten werden zweckgebunden und nach den geltenden Datenschutzbestimmungen verarbeitet. Die zugehörigen Informationen benennen Verantwortliche, Zwecke, Rechtsgrundlagen, Empfänger und Aufbewahrung. Freiwillige Einwilligungen werden gesondert eingeholt. Dokumentation und Leistungsnachweise sind wahrheitsgemäß; Berichtigungen bleiben nachvollziehbar."},{"key":"changes","heading":"§ 6 Änderungen, Verhinderung und Beendigung","text":"Laufzeit, Verhinderung, Absagen und Kündigungsrechte werden für die konkrete Vertragsart in den individuellen Vereinbarungen festgelegt. Zwingende gesetzliche Rechte bleiben gewahrt. Änderungen werden nachvollziehbar dokumentiert und den Beteiligten zugänglich gemacht; individuelle Abreden haben im gesetzlich vorgesehenen Umfang Vorrang. Nicht erbrachte Leistungen werden nicht als erbracht bestätigt."},{"key":"responsibility","heading":"§ 7 Verantwortung und Beschwerden","text":"Die Verantwortung richtet sich nach den anwendbaren gesetzlichen Regelungen. Eine pauschale Freizeichnung von Haftung ist nicht vereinbart. Anliegen und Beschwerden können an die genannte Kontaktstelle gerichtet werden und werden dokumentiert bearbeitet. Externe Beratungs-, Beschwerde- und Rechtsbehelfswege bleiben offen."},{"key":"annexes","heading":"§ 8 Anlagen und Ausfertigung","text":"Alle einbezogenen Anlagen werden mit Titel, Versionsstand und Datum aufgeführt und vor Abschluss bereitgestellt. Jede Partei erhält eine vollständige Ausfertigung. Individuelle Zusatzvereinbarungen werden erkennbar getrennt festgehalten und von den berechtigten Beteiligten bestätigt. Eine unwirksame Bestimmung wird nicht automatisch durch eine frei gewählte Regelung ersetzt."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(87,'{"version":1,"target":"company","sourceMode":"original","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"f0_aussteller_und_ausstellungsdatum","label":"Aussteller und Ausstellungsdatum","type":"multiline","required":true},{"key":"f1_aktenzeichen_und_gueltigkeit","label":"Aktenzeichen und Gültigkeit","type":"multiline","required":false},{"key":"f2_erforderliche_folgemassnahmen","label":"Erforderliche Folgemaßnahmen","type":"multiline","required":false},{"key":"f3_originaldatei_und_aufbewahrungsort","label":"Originaldatei und Aufbewahrungsort","type":"multiline","required":false}],"columns":[],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[{"key":"original","heading":"Zuordnung der Originalunterlage","text":"Dieses Begleitblatt dokumentiert den Eingang und die Zuordnung der Originalunterlage. Inhalt, Unterschriften, Gültigkeit und Änderungen ergeben sich aus dem beigefügten Original. Die zuständige Person prüft Aussteller, Vollständigkeit und erforderliche Folgemaßnahmen. Eine behördliche, ärztliche oder gerichtliche Erklärung wird durch dieses Blatt nicht ersetzt."}],"instructions":"Originalunterlage der ausstellenden Stelle hinterlegen. Das CareSuite-Begleitblatt ersetzt dieses Original nicht."}'::jsonb),
