INSERT INTO public.central_document_catalog(template_key,version,title,category_key,target,source_mode,review_status,definition_json)
SELECT d->>'key',(d->>'version')::integer,d->>'title',d->>'categoryKey',d->>'target',d->>'sourceMode','draft',d FROM definitions
ON CONFLICT (template_key,version) DO NOTHING;
COMMIT;
